PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    Motor : BOOL;
END_VAR_OUTPUT

VAR
    Motor_Latch : BOOL := FALSE;
END_VAR

IF NOT EStop THEN
    Motor := FALSE;
ELSIF Stop THEN
    Motor_Latch := FALSE;
ELSIF Start THEN
    Motor_Latch := TRUE;
END_IF

Motor := Motor_Latch;

END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT; (* Measured tank level in percent *)
END_VAR
VAR_OUTPUT
    PumpIn : BOOL; (* Inlet pump *)
    ValveOut : BOOL; (* Outlet drain valve *)
END_VAR
VAR
    pumpInAllowed : BOOL;
END_VAR

(* Control logic for inlet pump *)
IF Level <= 10 THEN
    pumpInAllowed := TRUE;
ELSIF Level >= 90 THEN
    pumpInAllowed := FALSE;
END_IF;

(* Prevent inlet pump from running if level is at or above the high limit *)
IF Level >= 90 THEN 
    PumpIn := FALSE;
ELSE
    PumpIn := pumpInAllowed;
END_IF;

(* Control logic for outlet valve *)
ValveOut := (Level >= 90);

END_PROGRAM

PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    TimerA : TON;
    TimerB : TON;
END_VAR

IF OpenA_Cmd AND NOT DoorB THEN
    TimerA(IN := TRUE, PT := T#0s);
ELSE
    TimerA(IN := FALSE, PT := T#0s);
END_IF;

IF OpenB_Cmd AND NOT DoorA THEN
    TimerB(IN := TRUE, PT := T#0s);
ELSE
    TimerB(IN := FALSE, PT := T#0s);
END_IF;

DoorA := TimerA.Q;
DoorB := TimerB.Q;

END_PROGRAM

