PROGRAM intersection
VAR_OUTPUT
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
END_VAR

VAR
    State : INT := 0;
    TimerGreen : TON;
    TimerYellow : TON;
    TimerAllRed : TON;
END_VAR

VAR CONSTANT
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

BEGIN
    CASE State OF
        0: // NS green, EW red
            NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
            EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
            TimerGreen(IN := TRUE, PT := PT_GREEN);
            TimerYellow(IN := FALSE, PT := PT_YELLOW);
            TimerAllRed(IN := FALSE, PT := PT_ALLRED);
            IF TimerGreen.Q THEN
                State := 1;
            END_IF;

        1: // NS yellow, EW red
            NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
            EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
            TimerGreen(IN := FALSE, PT := PT_GREEN);
            TimerYellow(IN := TRUE, PT := PT_YELLOW);
            TimerAllRed(IN := FALSE, PT := PT_ALLRED);
            IF TimerYellow.Q THEN
                State := 2;
            END_IF;

        2: // All-red clearance
            NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
            EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
            TimerGreen(IN := FALSE, PT := PT_GREEN);
            TimerYellow(IN := FALSE, PT := PT_YELLOW);
            TimerAllRed(IN := TRUE, PT := PT_ALLRED);
            IF TimerAllRed.Q THEN
                State := 3;
            END_IF;

        3: // EW green, NS red
            NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
            EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
            TimerGreen(IN := TRUE, PT := PT_GREEN);
            TimerYellow(IN := FALSE, PT := PT_YELLOW);
            TimerAllRed(IN := FALSE, PT := PT_ALLRED);
            IF TimerGreen.Q THEN
                State := 4;
            END_IF;

        4: // EW yellow, NS red
            NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
            EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
            TimerGreen(IN := FALSE, PT := PT_GREEN);
            TimerYellow(IN := TRUE, PT := PT_YELLOW);
            TimerAllRed(IN := FALSE, PT := PT_ALLRED);
            IF TimerYellow.Q THEN
                State := 5;
            END_IF;

        5: // All-red clearance
            NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
            EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
            TimerGreen(IN := FALSE, PT := PT_GREEN);
            TimerYellow(IN := FALSE, PT := PT_YELLOW);
            TimerAllRed(IN := TRUE, PT := PT_ALLRED);
            IF TimerAllRed.Q THEN
                State := 0;
            END_IF;
    ELSE
        State := 0; // Default state
    END_CASE;
END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;     // Level range: [0, 100]
    Temp : INT;      // Temp range: [0, 200]
    EStop : BOOL;    // Normally-closed input
END_VAR_INPUT

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    Timer : TON;
END_VAR

VAR CONSTANT
    LVL_HIGH : INT := 80;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
END_VAR CONSTANT

// State machine
IF NOT EStop THEN
    State := 0;
END_IF

CASE State OF
    0: // Idle
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF StartBatch AND EStop THEN
            State := 1; // Transition to Fill
        END_IF

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH THEN
            FillValve := FALSE;
            State := 2; // Transition to Heat
        END_IF

    2: // Heat
        FillValve := FALSE;
        DrainValve := FALSE;
        IF Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF

        IF Temp >= TEMP_SET THEN
            Timer(IN := TRUE, PT := PT_REACT);
            IF Timer.Q THEN
                State := 4; // Transition to Drain
                Timer(IN := FALSE);
            ELSE
                State := 3; // Transition to React
            END_IF
        END_IF

    3: // React
        FillValve := FALSE;
        DrainValve := FALSE;
        IF Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF

        Timer(IN := TRUE, PT := PT_REACT);
        IF Timer.Q THEN
            State := 4; // Transition to Drain
            Timer(IN := FALSE);
        END_IF

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            DrainValve := FALSE;
            State := 0; // Transition to Idle
        END_IF
END_CASE
END_PROGRAM

PROGRAM garage
VAR_INPUT
    EntrySensor : BOOL;
    ExitSensor : BOOL;
    EntryReq : BOOL;
END_VAR
VAR_OUTPUT
    FullSign : BOOL;
    EntryBarrierOpen : BOOL;
END_VAR
VAR
    Count : INT := 0;
    PrevEntry : BOOL := FALSE;
    PrevExit : BOOL := FALSE;
END_VAR

IF EntrySensor AND NOT PrevEntry THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
END_IF;

IF ExitSensor AND NOT PrevExit THEN
    IF Count > 0 THEN
        Count := Count - 1;
    END_IF;
END_IF;

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

FullSign := (Count = 3);
EntryBarrierOpen := (EntryReq AND Count < 3);
END_PROGRAM

PROGRAM motor_delay
