END_VAR_INPUT

VAR_OUTPUT
    Motor : BOOL; 
END_VAR_OUTPUT

VAR
    Timer : TON;
END_VAR

VAR CONSTANT
    PT_DELAY : TIME := T#3s; 
END_VAR CONSTANT

IF NOT EStop THEN 
    Timer(IN := FALSE, PT := PT_DELAY);
    Motor := FALSE;
ELSE
    Timer(IN := StartCmd, PT := PT_DELAY);
    Motor := Timer.Q;
END_IF

