PROGRAM star_delta
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    StarTimer : TON;
    StarTimerElapsed : BOOL;
END_VAR

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF StartPB THEN
    IF State = 0 THEN
        State := 1;
    END_IF
END_IF

CASE State OF
    0: (* Off *)
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
    1: (* Star *)
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        StarTimer(IN := TRUE, PT := T#3s);
        StarTimerElapsed := StarTimer.Q;
        IF StarTimerElapsed THEN
            State := 2;
            StarTimer(IN := FALSE);
        END_IF
    2: (* Delta *)
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
END_CASE

END_PROGRAM

PROGRAM ped_crossing
VAR_INPUT
    PedReq : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    CarGreen : BOOL;
    CarYellow : BOOL;
    CarRed : BOOL;
    PedWalk : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    TimerGreen : TON;
    TimerYellow : TON;
    TimerWalk : TON;
    MinGreenTimeReached : BOOL;
END_VAR

TimerGreen(IN := (State = 0), PT := T#3s);
TimerYellow(IN := (State = 1), PT := T#2s);
TimerWalk(IN := (State = 2), PT := T#3s);

MinGreenTimeReached := TimerGreen.Q;

CASE State OF
    0:
        CarGreen := TRUE;
        CarYellow := FALSE;
        CarRed := FALSE;
        PedWalk := FALSE;
        IF MinGreenTimeReached AND PedReq THEN
            State := 1;
        END_IF

    1:
        CarGreen := FALSE;
        CarYellow := TRUE;
        CarRed := FALSE;
        PedWalk := FALSE;
        IF TimerYellow.Q THEN
            State := 2;
        END_IF

    2:
        CarGreen := FALSE;
        CarYellow := FALSE;
        CarRed := TRUE;
        PedWalk := TRUE;
        IF TimerWalk.Q THEN
            State := 0;
        END_IF
END_CASE
END_PROGRAM

PROGRAM tank_cycle
VAR_INPUT
    Level : INT; // Tank level percent
    StartCycle : BOOL; // Start batch cycle
    EStop : BOOL; // Emergency stop, normally-closed: TRUE = healthy, FALSE = activated
END_VAR_INPUT

VAR_OUTPUT
    Pump : BOOL; // Inlet pump
    Valve : BOOL; // Outlet drain valve
END_VAR_OUTPUT

VAR
    State : INT := 0; // 0=Idle, 1=Filling, 2=Draining
END_VAR

IF NOT EStop THEN
    State := 0;
END_IF

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF StartCycle AND EStop AND Level < 90 THEN
            State := 1;
        END_IF

    1: // Filling
        Pump := (EStop AND Level < 90);
        Valve := FALSE;
        IF Level >= 90 THEN
            State := 2;
        END_IF

    2: // Draining
        Pump := FALSE;
        Valve := (EStop AND Level > 10);
        IF Level <= 10 THEN
            State := 0;
        END_IF

ELSE
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_CASE

END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT := 0;
    SeqTimer : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

SeqTimer(IN := (State = 1), PT := PT_SEQ);

CASE State OF
    0: // Off state
        C1 := FALSE;
        C2 := FALSE;
        IF StartPB AND NOT EStop THEN
            State := 1; // Transition to Starting
        END_IF
    1: // Starting state
        C1 := FALSE;
        C2 := TRUE;
        IF NOT EStop AND SeqTimer.Q THEN
            State := 2; // Transition to Running
        ELSIF StopPB OR NOT EStop THEN
            State := 0; // Transition to Off
        END_IF
    2: // Running state
        C1 := TRUE;
        C2 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := 0; // Transition to Off
        END_IF
END_CASE

END_PROGRAM

PROGRAM burner
VAR_INPUT
    StartPB : BOOL; 
    StopPB : BOOL;
    EStop : BOOL; 
    Flame : BOOL;
END_VAR

VAR_OUTPUT
    Fan : BOOL;
    Fuel : BOOL;
    Ignition : BOOL;
END_VAR

VAR
    State : INT := 0; 
    PurgeTimer : TON;
    IgniteTimer : TON;
END_VAR

VAR CONSTANT
    PT_PURGE : TIME := T#3s;
    PT_IGN : TIME := T#2s;
END_VAR

PurgeTimer(IN := (State = 1), PT := PT_PURGE);
IgniteTimer(IN := (State = 2), PT := PT_IGN);

IF NOT EStop OR StopPB THEN
    State := 0;
ELSIF State = 0 THEN
    IF StartPB THEN
        State := 1;
    END_IF
ELSIF State = 1 THEN 
    Fan := TRUE;
    IF PurgeTimer.Q THEN
        State := 2;
    END_IF
ELSIF State = 2 THEN 
    Fan := TRUE;
    Fuel := TRUE;
    Ignition := TRUE;
    IF IgniteTimer.Q THEN
        IF Flame THEN
            State := 3;
        ELSE
            State := 0;
        END_IF
    END_IF
ELSIF State = 3 THEN 
    Fan := TRUE;
    Fuel := TRUE;
    IF NOT Flame THEN
        State := 0;
    END_IF
END_IF

Fan := (State >= 1) AND (State <= 3);
Fuel := (State >= 2) AND (Flame OR State = 2);
Ignition := (State = 2);

END_PROGRAM

PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0; // 0 = pump 1 leads, 1 = pump 2 leads
    PrevDemand : BOOL := FALSE;
    LeadSwitchTimer : TON;
END_VAR

// Check for falling edge of Demand to toggle Lead
IF NOT Demand AND PrevDemand THEN
    // Use a timer to debounce any transient signals, ensuring stability
    LeadSwitchTimer(IN := TRUE, PT := T#1s);
    IF LeadSwitchTimer.Q THEN
        Lead := 1 - Lead; // Toggle Lead
    END_IF;
ELSE
    LeadSwitchTimer(IN := FALSE, PT := T#1s);
END_IF;

// Update PrevDemand for edge detection in next cycle
PrevDemand := Demand;

// Determine pump states based on Lead, Demand, and EStop conditions
IF EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSIF Demand THEN
    CASE Lead OF
        0: // Pump 1 leads
            Pump1 := TRUE;
            Pump2 := FALSE;
        1: // Pump 2 leads
            Pump1 := FALSE;
            Pump2 := TRUE;
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_CASE;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;
END_PROGRAM

PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    MotorOpen : BOOL := FALSE;
    MotorClose : BOOL := FALSE;
END_VAR_OUTPUT

VAR
    State : INT := 0;
END_VAR

CASE State OF
    0: (* Idle *)
        MotorOpen := FALSE;
        MotorClose := FALSE;

        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT CloseLimit AND NOT Obstruction THEN
            State := 2;
        END_IF;

    1: (* Opening *)
        MotorOpen := TRUE;
        MotorClose := FALSE;

        IF OpenLimit THEN
            State := 0;
        END_IF;

    2: (* Closing *)
        MotorOpen := FALSE;
        MotorClose := TRUE;

        IF CloseLimit OR Obstruction THEN
            State := 0;
        END_IF;

ELSE
    State := 0; (* Reset to Idle for any unknown state *)
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR_OUTPUT

VAR
    State : INT := 0;
    Timer1 : TON;
    Timer2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

BEGIN
    IF NOT EStop THEN
        State := 0;
    ELSIF StopPB THEN
        State := 0;
    ELSE
        CASE State OF
            0:
                IF StartPB THEN
                    State := 1;
                END_IF;
            1:
                C3 := TRUE;
                Timer1(IN := TRUE, PT := PT_SEQ);
                IF Timer1.Q THEN
                    State := 2;
                END_IF;
            2:
                C3 := TRUE;
                C2 := TRUE;
                Timer2(IN := TRUE, PT := PT_SEQ);
                IF Timer2.Q THEN
                    State := 3;
                END_IF;
            3:
                C3 := TRUE;
                C2 := TRUE;
                C1 := TRUE;
        END_CASE;
    END_IF;

    IF State = 0 THEN
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        Timer1(IN := FALSE);
        Timer2(IN := FALSE);
    END_IF;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR_INPUT

VAR_OUTPUT
    Done : BOOL;
END_VAR_OUTPUT

VAR
    Count : INT := 0;
    PrevTrigger : BOOL := FALSE;
END_VAR

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF Trigger AND NOT PrevTrigger THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
    IF Count = 3 THEN
        Done := TRUE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM
